const pr = $input.first().json.body.pull_request;
const labels = (pr.labels || []).map(l => l.name);
let bump = 'patch';
if (labels.includes('release:major')) bump = 'major';
else if (labels.includes('release:minor')) bump = 'minor';
return [{ json: {
  bump,
  prNumber: pr.number,
  prTitle: pr.title,
  repoOwner: $input.first().json.body.repository.owner.login,
  repoName: $input.first().json.body.repository.name
}}];
